  function saveLoginAccount(){
    const f=loginForm();if(!f){authStatus('未识别到可保存的登录表单');return false;}
    const account=f.account.value.trim(),password=f.password.value;if(!account||!password){authStatus('先在网页登录框填写账号和密码');return false;}
    const all=GM_getValue(AUTH_ACCOUNTS,{});all[location.origin]={account,password,enabled:!!ui.autoLogin?.checked};GM_setValue(AUTH_ACCOUNTS,all);authStatus('已保存到本机，绑定当前登录站点');return true;
  }
  function clearLoginAccount(){const all=GM_getValue(AUTH_ACCOUNTS,{});delete all[location.origin];GM_setValue(AUTH_ACCOUNTS,all);if(ui.autoLogin)ui.autoLogin.checked=false;authStatus('已删除当前站点的登录信息');}
  function loginField(el,value){const setter=Object.getOwnPropertyDescriptor(el.ownerDocument.defaultView.HTMLInputElement.prototype,'value')?.set;if(setter)setter.call(el,value);else el.value=value;for(const type of ['input','change'])el.dispatchEvent(new Event(type,{bubbles:true}));}
  async function loginTick(manual=false){
    const f=loginForm();if(!f)return false;
    if(verificationPresent()){authStatus('等待你手动拖动滑块，验证完成后继续');return true;}
    const r=readAuth()||makeAuthRequest(),all=GM_getValue(AUTH_ACCOUNTS,{}),saved=all[location.origin];
    if(!saved?.enabled&&!manual){authStatus('可保存本页账号密码，并开启自动尝试登录');return true;}
    if(!saved?.account||!saved?.password){authStatus('先填写网页登录框，再保存账号密码');return true;}
    const attemptKey=`baka.login.attempt.${location.origin}.${owner}`,last=GM_getValue(attemptKey,null),id=r?.id||'manual-session';
    if(manual&&last&&Date.now()-last.at<3000){authStatus('刚刚已尝试，请稍候查看结果');return true;}
    if(!manual&&last&&(last.id===id||Date.now()-last.at<120000)){authStatus('已尝试登录，请检查结果；不会重复点击');return true;}
    if($$('.error,.error-message,.tips,.tips_error,[role="alert"]').some(e=>visible(e)&&/密码.{0,8}(错误|不正确)|账号.{0,8}(错误|不存在|锁定)|频繁|次数过多/.test(text(e)))){authStatus('登录信息或频率异常，请手动检查');return true;}
    if($$('input[type="checkbox"]',f.form).some(e=>visible(e)&&!e.checked&&(e.required||/协议|条款/.test(text(e.parentElement))))){authStatus('请先自行确认登录条款');return true;}
    if(f.account.value.trim()&&f.account.value.trim()!==saved.account){authStatus('当前账号与保存账号不同，请重新保存或手动登录');return true;}
    if(f.password.value&&f.password.value!==saved.password){authStatus('当前密码已修改，请重新保存或手动登录');return true;}
    if(f.button.disabled){authStatus('登录按钮暂不可用');return true;}
    loginField(f.account,saved.account);loginField(f.password,saved.password);
    GM_setValue(attemptKey,{id,at:Date.now()});if(r)GM_setValue(AUTH_REQUEST,{...r,loginOrigin:location.origin});
    f.button.click();authStatus('已尝试登录，遇到验证请手动完成');return true;
  }
  async function resumeAuthenticated(r){
    if(r.targetOwner&&r.targetOwner!==owner)return false;
    const target=new URL(r.url),here=new URL(location.href);
    const same=readerPage?here.pathname===target.pathname&&readIdentity()===`${target.searchParams.get('courseId')||''}/${target.searchParams.get('knowledgeId')||''}`:courseId()===r.course&&chapterId()===r.chapter;
    if(!same||(!readerPage&&!$('#mainid'))||verificationPresent()||pageError())return false;
    GM_setValue(AUTH_REQUEST,null);S.authHold=false;S.visit=new Set(r.visits||[]);S.cardDone=new Set(r.cards||[]);
    if(r.reading){S.reading=r.reading;GM_setValue(TICKET,{...r.reading,state:'active',reader:owner,at:Date.now()});}
    await start(false,false,true);
    if(r.pendingSubmit)S.autoHold={key:pageKey(),at:Date.now(),reason:'重新登录后核对提交结果',submission:true};
    return true;
  }
  async function authTick(){
    if(loginForm())return loginTick();
    const r=readAuth();
    if(loginOrigin()||landingPage){
      if(r&&(!r.loginOrigin||r.loginOrigin===location.origin||landingPage)&&!verificationPresent()&&/退出登录|退出|个人中心|个人空间|我的课程/.test(text(document.body))&&!$('input[type="password"]')){
        if(r.state!=='entering'||r.targetOwner!==owner){GM_setValue(AUTH_REQUEST,{...r,state:'entering',targetOwner:owner});authStatus('登录成功，返回原章节');recoveryIO.go(r.url);}
      }return true;
    }
    if(S.started&&verificationPresent()){suspendForAuth('verify');return true;}
    const error=pageError();
    if(S.started&&error?.kind==='manual'&&/登录|登陆/.test(error.message)){suspendForAuth('login');return true;}
    if(r&&(r.owner===owner||r.targetOwner===owner)){
      if(await resumeAuthenticated(r))return true;
      if(S.authHold||r.state==='waiting'){authStatus('等待登录或验证完成');return true;}
    }
    return false;
  }
  function mountLogin(){
    const host=document.createElement('div');host.id='baka-login-helper';host.style.cssText='position:fixed;right:18px;bottom:18px;z-index:2147483000;color-scheme:light';
    const root=host.attachShadow({mode:'closed'});root.innerHTML=`<style>:host{all:initial}section{font:13px/1.6 "Microsoft YaHei",sans-serif;color:#24465f;background:#f7fcfff2;border:1px solid #c5dfef;border-radius:16px;padding:18px;width:280px;box-shadow:0 10px 36px #16365433}header{font-size:17px;font-weight:bold}small{font-size:11px;color:#627f94}p{margin:10px 0}button{font:inherit;border:1px solid #bcd5e5;border-radius:8px;background:white;color:#326788;padding:8px;cursor:pointer;margin:4px 0;width:100%}label{display:flex;justify-content:space-between;margin:12px 0}.status{background:#eaf5fc;border-radius:8px;padding:8px}</style><section><header>Baka助手 <small>0.9</small></header><p class="status">登录辅助</p><label>自动尝试登录<input class="auto" type="checkbox"></label><button class="saveLogin">保存本页账号密码</button><button class="retryLogin">尝试登录一次</button><button class="clearLogin">删除保存的账号密码</button><button class="cancelLogin">取消章节恢复</button><small>先在网页填写账号密码。保存在本机油猴存储（未加密），仅用于当前登录站点。</small></section>`;
    ui.authStatus=$('.status',root);ui.autoLogin=$('.auto',root);ui.autoLogin.checked=!!GM_getValue(AUTH_ACCOUNTS,{})[location.origin]?.enabled;
    ui.autoLogin.onchange=()=>{const all=GM_getValue(AUTH_ACCOUNTS,{}),p=all[location.origin];if(p){p.enabled=ui.autoLogin.checked;GM_setValue(AUTH_ACCOUNTS,all);}authStatus(ui.autoLogin.checked?'已开启，请先保存登录信息':'自动登录已关闭');};
    $('.saveLogin',root).onclick=saveLoginAccount;$('.clearLogin',root).onclick=clearLoginAccount;$('.retryLogin',root).onclick=()=>void loginTick(true);$('.cancelLogin',root).onclick=()=>{cancelAuthResume(true);authStatus('已取消章节恢复');};
    document.body.append(host);
  }
  function leavePage(){rememberSession(true);S.epoch++;S.started=false;S.busy=false;requestHandle?.abort?.();requestHandle=null;release();}
  async function restorePage(e){if(e.persisted&&activeHere()&&!overviewPage&&!loginOrigin()&&!landingPage){S.started=false;await start(false,false,true);}}

  function optionsFor(root,popup=false){
    let nodes=popup?$$('.ans-videoquiz-opt',root):$$('li[role="radio"],li[role="checkbox"],.Zy_ulTop>li,.Zy_ulBottom>li',root);
    nodes=nodes.filter(visible);
    if(!nodes.length)nodes=$$('input[type="radio"],input[type="checkbox"]',root).map(e=>e.closest('label')||e.parentElement);
    return [...new Set(nodes)].map((el,i)=>{
      const input=$('input[type="radio"],input[type="checkbox"]',el);
      const marker=$('.num_option,.num_option_dx',el),display=text(marker),stored=marker?.getAttribute('data');
      const label=/^[A-Z]$/.test(display)?display:String.fromCharCode(65+i);
      return {el,input,label,value:stored||input?.value||label,text:text(el)};
    });
  }
  function parseQuestion(root,popup=false){
    const titleEl=popup?$('.tkTopic_title',root):$('.Zy_TItle .fontLabel,.Zy_TItle,.question-title,.stem',root);
    const title=text(titleEl)||text(root).slice(0,12000);
    const options=optionsFor(root,popup);
    let fields=$$('textarea,input[type="text"],[contenteditable="true"]',root).filter(e=>visible(e)&&!e.disabled&&!e.readOnly);
    for(const f of $$('iframe',root))try{if(f.contentDocument?.body.isContentEditable)fields.push(f.contentDocument.body);}catch{}
    fields=fields.filter((e,i,a)=>!a.some((p,j)=>i!==j&&p.contains(e)));
    const multi=/多选/.test(title)||options.some(o=>o.input?.type==='checkbox'||o.el.getAttribute('role')==='checkbox'||o.el.getAttribute('qtype')==='1'||!!$('.num_option_dx',o.el)||/addMultipleChoice\s*\(/.test(o.el.getAttribute('onclick')||''));
    const type=multi?'multi':options.length?'single':/填空/.test(title)?'blanks':'text';
    const visual=!!$('.font-cxsecret,img,svg,canvas',root)||!text(titleEl)||/[\uE000-\uF8FF\uFFFD]/.test(title);
    const id=$('[qid]',root)?.getAttribute('qid')||root.closest('[id^="question"]')?.id.replace(/^question/,'')||root.id.replace(/^question/,'')||'';
    return {root,title,options,fields,type,visual,id,popup,judge:/判断题/.test(title)||options.some(o=>o.el.getAttribute('qtype')==='3'),
      fingerprint:JSON.stringify([id,type,title,options.map(o=>[o.label,o.value,o.text]),$$('img',root).map(e=>e.currentSrc||e.src)])};
  }
  function questionRoots(d){
    return $$('.TiMu,.questionLi,.question-item',d).filter(visible)
      .filter(e=>!$('.TiMu,.questionLi,.question-item',e));
  }
  function checked(q,o){
    if(o.input)return o.input.checked;
    const saved=q.id?$(`input[id="answer${q.id}"]`,q.root):null;
    if(saved?.value){const value=saved.value.trim(),stored=o.value||o.label;return value.split(/[\s,;|]+/).includes(stored)||(/^[A-Z]+$/.test(value)&&stored.length===1&&value.includes(stored));}
    if(o.el.hasAttribute('aria-checked'))return o.el.getAttribute('aria-checked')==='true';
    if($('.check_answer,.check_answer_dx,.checked,.selected',o.el)||o.el.classList.contains('check_answer'))return true;
    if(q.id){const value=$(`input[id="answer${q.id}"]`,q.root)?.value||'',stored=o.value||o.label;return value.split(/[\s,;|]+/).includes(stored)||(/^[A-Z]+$/.test(value)&&value.includes(stored));}
    return false;
  }
  function fieldValue(e){return e.isContentEditable?text(e):e.value.trim();}
  function filled(q){return q.options.length?q.options.some(o=>checked(q,o)):q.fields.length>0&&q.fields.every(e=>!!fieldValue(e));}
  function validateAnswer(q,a){
    if(q.judge){
      const raw=a.choices.length===1?a.choices[0]:!a.choices.length?a.answer:'';
      const truth=/^(true|正确|对|√|✓)$/i.test(raw)?'true':/^(false|错误|错|×|✗)$/i.test(raw)?'false':null;
      if(truth!==null){const option=q.options.find(o=>o.value===truth||text($('a',o.el))===(truth==='true'?'对':'错'));if(option)a.choices=[option.label];}
    }
    if(q.options.length){
      if(!a.choices.length||new Set(a.choices).size!==a.choices.length||(q.type==='single'&&a.choices.length!==1)||a.choices.some(l=>!q.options.some(o=>o.label===l)))throw Error('答案与选项不匹配');
    }else if(q.type==='blanks'||q.fields.length>1){if(a.blanks.length!==q.fields.length||a.blanks.some(v=>!v.trim()))throw Error('填空数量不匹配');}
    else if(q.fields.length!==1||!a.answer.trim())throw Error('题型暂不支持自动填写');
  }
  async function fill(q,a,ctx){
    validateAnswer(q,a);if(!valid(ctx)||!q.root.isConnected)throw Error('页面已切换');
    if(q.options.length){
      for(const o of q.options){const want=a.choices.includes(o.label),has=checked(q,o);
        if(want!==has&&(q.type==='multi'||want))(o.input||o.el).click();}
      const until=Date.now()+1500;
      while(Date.now()<until&&q.options.some(o=>checked(q,o)!==a.choices.includes(o.label))){await sleep(100);if(!valid(ctx)||!q.root.isConnected)throw Error('页面已切换');}
      if(q.options.some(o=>checked(q,o)!==a.choices.includes(o.label))){
        log(`题目 ${q.id} 填写核验失败\n期望：${a.choices.join(',')}\n实际：${q.options.filter(o=>checked(q,o)).map(o=>o.label).join(',')||'未选中'}\n映射：${q.options.map(o=>`${o.label}→${o.value}`).join('，')}`);
        throw Error('页面未接受选项，题号和选项映射已记录');
      }
    }else{
      const values=q.type==='blanks'||q.fields.length>1?a.blanks:[a.answer];
      q.fields.forEach((e,i)=>{
        if(e.isContentEditable)e.textContent=values[i];
        else {const W=e.ownerDocument.defaultView,proto=e.tagName==='TEXTAREA'?W.HTMLTextAreaElement.prototype:W.HTMLInputElement.prototype;
          Object.getOwnPropertyDescriptor(proto,'value').set.call(e,values[i]);}
        const W=e.ownerDocument.defaultView;e.dispatchEvent(new W.Event('input',{bubbles:true}));e.dispatchEvent(new W.Event('change',{bubbles:true}));e.dispatchEvent(new W.Event('blur',{bubbles:true}));
      });
      if(q.fields.some((e,i)=>fieldValue(e)!==values[i].trim()))throw Error('页面未接受文字答案');
    }
  }
  function popup(d){
    const submit=$('#videoquiz-submit',d),title=$('.tkTopic_title',d);
    if(!visible(submit)||!visible(title))return null;
    let root=title.parentElement;
    while(root&&root!==d.body&&(!root.contains(submit)||!$('.ans-videoquiz-opt',root)))root=root.parentElement;
    const q=parseQuestion(root||d.body,true);q.submit=submit;return q;
  }
  function combinations(q){
    const labels=q.options.map(o=>o.label);if(q.type!=='multi')return labels.map(l=>[l]);
    if(labels.length>8)return [];
    return Array.from({length:(1<<labels.length)-1},(_,i)=>labels.filter((_,j)=>(i+1)&(1<<j)))
      .sort((a,b)=>(a.length===1)-(b.length===1)||a.length-b.length).slice(0,32);
  }
  async function solvePopup(q,ctx){
    S.videoWatch=null;
    const d=q.root.ownerDocument,id=ctx.key+q.fingerprint;
    if(visible($('#spanHas',d))){status('弹题已通过');return;}
    if(cfg.popup==='off'){status('等待回答视频弹题');return;}
    if(S.failed.has(id)){status('本题需要手动处理');return;}
    const record=S.quiz.get(id)||{index:0,choices:combinations(q)};S.quiz.set(id,record);
    try{
      let a;
      if(cfg.popup==='ai'){
        if(record.index)throw Error('AI 答案未通过');status('AI 正在回答弹题');a=await answer(q,ctx);
      }else{
        const choices=record.choices[record.index];if(!choices)throw Error('试答次数已用完');
        a={choices,blanks:[],answer:'',uncertain:false};status(`弹题试答 ${record.index+1}`);
      }
      if(!valid(ctx))return;await fill(q,a,ctx);
      if(!cfg.popupSubmit){pause('弹题已填写，等待提交');return;}
      const feedback=$$('#spanHas,#spanNot,#spanNotBack',d);let changed=false;
      const observer=new MutationObserver(()=>{changed=true;});feedback.forEach(e=>observer.observe(e,{attributes:true,childList:true,subtree:true}));
      let hidden=!$$('#spanNot,#spanNotBack',d).some(visible);
      try{
        if(!valid(ctx))return;q.submit.click();record.index++;
        const end=Date.now()+18000;
        while(Date.now()<end){await sleep(600);if(!valid(ctx)||!q.submit.isConnected||popup(d)?.fingerprint!==q.fingerprint)return;
          if(visible($('#spanHas',d)))return;
          const wrong=$$('#spanNot,#spanNotBack',d).some(visible);if(!wrong)hidden=true;
          if(wrong&&(changed||hidden)){if(cfg.popup==='ai')throw Error('AI 答案未通过');return;}}
        throw Error('没有收到答题反馈');
      }finally{observer.disconnect();}
    }catch(e){if(valid(ctx)){S.failed.add(id);if(cfg.fullAuto){fault('视频弹题需要处理：'+e.message);}else status(e.message);}}
  }
  function submitButton(d){return $$('.btnSubmit,button,[role="button"]',d).find(e=>visible(e)&&/^提交(?:作业|答案)?$/.test(text(e)));}
  function pendingIdentity(q){return [courseId(),chapterId(),$('[id^="dct"].active')?.getAttribute('cardid')||'',q.id||q.fingerprint].join('|');}
  function resolveQuestion(q){if(S.deferred.delete(pendingIdentity(q))){GM_setValue('cirno.pending.v5',[...S.deferred.values()]);ui.updatePending?.();}}
  function deferQuestion(q,reason){
    const item={key:pendingIdentity(q),course:courseId(),chapter:chapterId(),card:$('[id^="dct"].active')?.getAttribute('cardid')||'',id:q.id,title:q.visual?'截图题 '+(q.id||''):q.title.slice(0,120),reason:redact(reason)};
    S.deferred.set(item.key,item);
    GM_setValue('cirno.pending.v5',[...S.deferred.values()]);log(`待处理：${item.title}\n章节 ${item.chapter}\n${item.reason}`);ui.updatePending?.();
  }
  async function leaveIncompleteWork(d,ctx){
    const saveButton=$$('.btnSave,button,[role="button"]',d).find(e=>visible(e)&&/^暂时保存$|^保存(?:作业|答案)?$/.test(text(e)));
    if(saveButton){saveButton.click();await sleep(800);}
    if(valid(ctx)){log('本页有待处理题目，未提交；继续下一项');advance();}
  }
  async function doHomework(d,ctx){
    if(!cfg.homework&&!S.single){advance();return;}
    if($('.newAnswerBx',d)&&!submitButton(d)){questionRoots(d).map(r=>parseQuestion(r)).forEach(resolveQuestion);advance();return;}
    if(/\/exam\//i.test(d.location.pathname)){pause('考试页面不在当前任务范围');return;}
    const roots=questionRoots(d);if(!roots.length){waitContent('等待题目加载');return;}
    const qs=roots.map(r=>parseQuestion(r));
    if(qs.some(q=>!q.options.length&&!q.fields.length)&&!cfg.fullAuto){
      if(!submitButton(d)){advance();return;}
      pause('遇到暂不支持的题型');return;
    }
    let unresolved=false;
    for(let i=0;i<qs.length;i++){
      const q=qs[i];if(filled(q)&&!S.replaceAnswers){resolveQuestion(q);continue;}
      if(!q.options.length&&!q.fields.length){if(cfg.fullAuto&&!S.single){deferQuestion(q,'题型暂不支持自动填写');unresolved=true;continue;}pause('遇到暂不支持的题型');return;}
      status(`AI 答题 ${i+1} / ${qs.length}`);
      try{
        const a=await answer(q,ctx);if(!valid(ctx))return;
        await fill(q,a,ctx);progress();resolveQuestion(q);log(`${i+1}. ${a.choices.join('')||a.blanks.join('；')||a.answer}\n${a.explanation||''}`);
      }catch(e){if(!valid(ctx))return;if(cfg.fullAuto&&!S.single&&e.code==='UNCERTAIN'){deferQuestion(q,e.message);unresolved=true;continue;}fault(e.message);return;}
    }
    if(!valid(ctx))return;
    if(unresolved){await leaveIncompleteWork(d,ctx);return;}
    if(!qs.every(filled)){fault('尚有未填写的题目');return;}
    if(S.replaceAnswers){pause('已重新填写本页，请核对后手动提交');return;}
    if(!cfg.autoSubmit){pause('已填写，等待你提交');return;}
    const button=submitButton(d);if(!button){fault('未识别到提交按钮');return;}
    if(S.submit){status('等待提交结果');return;}
    S.submit={d,key:ctx.key,at:Date.now(),confirmed:false};button.click();status('正在提交');
  }
  function handleSubmission(){
    const p=S.submit;if(!p)return false;
    if(p.key!==pageKey()){S.submit=null;return false;}
    const d=p.d;
    const confirm=documents().flatMap(doc=>$$('a[onclick*="submitCheckTimes"],#popok',doc)).find(visible);
    if(!p.confirmed&&confirm){
      const dialog=confirm.closest('.AlertCon02,.popSetDiv,.popDiv,[role="dialog"]')||confirm.parentElement.parentElement;
    const wording=text(dialog);
      if(/提交/.test(wording)&&!/未作答|未完成|验证码|重做|考试|剩余.*0次/.test(wording)){
        if(cfg.autoSubmit){p.confirmed=true;confirm.click();}
      }else{fault('提交需要手动确认');return true;}
    }
    if(visible($('#submitBack',d))){fault('答案未达到通过标准');return true;}
    const card=cardDoc(),markers=$$('.ans-job-icon',card);
    if(markers.length&&markers.every(taskDone)){if(bankBeforeAdvance())return true;S.submit=null;advance();return true;}
    if(!d.documentElement?.isConnected||!submitButton(d)){
      const result=text(d.body);
      if(/已提交|待批阅|提交成功|成绩|得分/.test(result)){if(bankBeforeAdvance())return true;S.submit=null;advance();return true;}
    }
    if(Date.now()-p.at>30000){fault('未确认提交成功，请检查页面');if(S.autoHold)S.autoHold.submission=true;}
    return true;
  }
  function catalogue(){
    return $$('#content1 .posCatalog_name[onclick]').map(el=>{
      const holder=el.closest('[id^="cur"]');
      const match=(el.getAttribute('onclick')||'').match(/getTeacherAjax\([^,]+,[^,]+,\s*['"]([^'"]+)/);
      return {el,id:holder?.id.replace(/^cur/,'')||match?.[1]||'',complete:!!$('.icon_Completed',holder),
        remaining:Number(text($('.orangeNew',holder)))||null,reading:/阅读/.test(el.title||text(el))};
    }).filter(x=>x.id);
  }
  function navigate(el,label){
    if(S.pending)return;progress();S.epoch++;S.pending={key:pageKey(),at:Date.now()};status(label);el.click();
  }
  function cardIdentity(el){return [courseId(),chapterId(),el?.getAttribute('cardid')||el?.id||''].join('/');}
  function cardRank(el){const label=el.title||text(el);return /视频/.test(label)?0:/测验|习题|作业|练习/.test(label)?1:/阅读/.test(label)?2:3;}
  function orderedCards(){return $$('[id^="dct"][cardid]').sort((a,b)=>cardRank(a)-cardRank(b));}
  function prioritizeVideo(){
    if(!cfg.fullAuto||S.single)return false;
    const active=$('[id^="dct"].active');
    if(active&&cardRank(active)===0)return false;
    const next=orderedCards().find(el=>cardRank(el)===0&&!S.cardDone.has(cardIdentity(el)));
    if(!next)return false;navigate(next,'先检查本节视频');return true;
  }
  function advance(){
    if(!S.started||S.pending)return;
    if(bankBeforeAdvance())return;
    if(S.single){pause('本页处理完成');return;}
    const active=$('[id^="dct"].active'),tabs=$$('[id^="dct"][cardid]');
    S.pageDone.add(pageKey());
    if(active)S.cardDone.add(cardIdentity(active));
    const index=tabs.indexOf(active);
    const next=cfg.fullAuto?orderedCards().find(el=>el!==active&&!S.cardDone.has(cardIdentity(el))):(index>=0?tabs.slice(index+1).find(el=>cfg.homework||!/测验|习题|作业|练习/.test(el.title||text(el))):null);
    if(next){navigate(next,'切换学习内容');return;}
    const items=catalogue(),pos=items.findIndex(x=>x.id===chapterId());
    const visitedKey=`${courseId()}/${chapterId()}`;S.visit.add(visitedKey);
    const ordered=[...items.slice(Math.max(0,pos+1)),...items.slice(0,Math.max(0,pos))];
    const skipped=new Set(readFlow()?.skipped||[]);
    const candidate=ordered.find(x=>!skipped.has(x.id)&&!S.visit.has(`${courseId()}/${x.id}`)&&(!x.complete||(cfg.reading&&x.reading)));
    if(candidate){navigate(candidate.el,'前往未完成任务');return;}
    if(!items.length){const button=$('#prevNextFocusNext');if(visible(button)){navigate(button,'前往下一节');return;}}
    const unresolved=[...S.deferred.values()].filter(x=>x.course===courseId()).length;
    pause(unresolved?`本轮结束 · ${unresolved} 题待处理`:'本轮任务已处理完毕');
  }
  function firstUnfinished(){
    const item=catalogue().find(x=>!x.complete&&x.remaining!==null);
    if(!item){status('没有找到明确未完成的章节');return;}
    S.visit.clear();navigate(item.el,'定位未完成任务');
  }
  function videoWatchdog(v=null,reason='视频加载中'){
    const now=Date.now(),key=pageKey(),time=Number(v?.currentTime)||0;
    let w=S.videoWatch;
    if(!w||w.key!==key||w.video!==v)w=S.videoWatch={key,video:v,time,at:now,lastPlay:0};
    if(v&&!v.error&&time>w.time+0.2){w.time=time;w.at=now;S.lastVideoProgress=now;progress();}
    if(v&&(S.manual.has(v)||S.playBlocked?.has(v))){w.at=now;return false;}
    const seconds=Math.floor((now-w.at)/1000);
    if(seconds>=300){recoverPage(`${reason}持续 5 分钟，返回课程重试`);return true;}
    if(seconds>=5||v?.error||!v)status(`${reason} · ${seconds}/300 秒后恢复`);
    return false;
  }
  async function playVideo(v){
    if(!S.bound.has(v)){
      S.bound.add(v);const box=v.closest('.video-js')||v.parentElement;
      for(const type of ['pointerdown','keydown'])box.addEventListener(type,e=>{if(e.isTrusted)S.gesture.set(v,Date.now());},true);
      v.addEventListener('pause',()=>{if(Date.now()-(S.gesture.get(v)||0)<1000&&!v.ended)S.manual.add(v);});
      v.addEventListener('playing',()=>{S.manual.delete(v);S.playBlocked?.delete(v);});
    }
    if(S.manual.has(v)){S.videoWatch=null;status('视频已手动暂停');return;}
    if(S.playBlocked?.has(v)){S.videoWatch=null;status('请点击一次视频播放');return;}
    if(videoWatchdog(v,v.error?'视频加载失败':v.ended?'等待视频任务完成标记':'视频等待加载或播放进度'))return;
    if(v.error||v.ended)return;
    v.muted=cfg.muted;
    if(v.paused&&Date.now()-S.videoWatch.lastPlay>5000){
      S.videoWatch.lastPlay=Date.now();const ctx=currentEpoch();
      Promise.resolve().then(()=>v.play()).catch(e=>{if(valid(ctx)&&e.name==='NotAllowedError'){S.playBlocked||=new WeakSet();S.playBlocked.add(v);status('请点击一次视频播放');}});
    }
    if(Date.now()-S.videoWatch.at<5000)status('视频播放中');
  }
  async function openReader(root){
    if(!cfg.reading){advance();return;}
    const d=documents(root).find(d=>$('.readInfo',d));
    if(!d){status('等待阅读入口');return;}
    const ticket={id:crypto.randomUUID(),parent:owner,course:courseId(),key:pageKey(),at:Date.now(),state:'pending'};
    GM_setValue(TICKET,ticket);S.waitReader=ticket;release();
    const original=unsafeWindow.open;
    try{
      unsafeWindow.open=function(url,...args){
        const u=new URL(url,location.href);
        if(u.protocol==='https:'&&/(^|\.)chaoxing\.com$/.test(u.hostname)&&/\/zt\/|\/course\//.test(u.pathname)){
          u.searchParams.set('cirnoReader',ticket.id);GM_openInTab(u.href,{active:true,setParent:true});return null;
        }
        return original.call(unsafeWindow,url,...args);
      };
      $('.readInfo',d).click();status('正在打开阅读页');
    }finally{unsafeWindow.open=original;}
  }
  async function waitReader(){
    const t=GM_getValue(TICKET,null);
    if(!t||t.id!==S.waitReader.id){pause('阅读会话已失效');S.waitReader=null;return;}
    if(t.state==='done'||t.state==='skipped'){
      if(t.state==='skipped')markSkipped(t.reason||'阅读未完成');
      S.waitReader=null;GM_setValue(TICKET,null);
      if(await acquire()){S.epoch++;advance();}return;
    }
    if(t.state==='stopped'){S.waitReader=null;pause('阅读已暂停');return;}
    if(t.state==='pending'&&Date.now()-t.at>60000){S.waitReader=null;if(await acquire())fault('阅读新窗口未连接');return;}
    if(t.state==='active'&&Date.now()-(t.lastSeen||t.at)>180000){S.waitReader=null;if(await acquire())fault('阅读页连接中断');return;}
    status(t.state==='active'?'阅读页正在处理':'等待阅读页打开');
  }
  function readerLinks(){return $$('a[href*="/ztnodedetailcontroller/visitnodedetail"]');}
  function readIdentity(){const u=new URL(location.href);return `${u.searchParams.get('courseId')||''}/${u.searchParams.get('knowledgeId')||''}`;}
  function readerNext(){return $$('a[href]',document).find(a=>/^下一页\s*[›»>]?/.test(text(a))&&visible(a)&&!a.classList.contains('disabled')&&a.getAttribute('aria-disabled')!=='true'&&!/^javascript:|^#$/.test(a.getAttribute('href'))&&a.href!==location.href&&flowURL(a.href));}
  function readerScroller(){
    const body=$('#ztMainBoxFocus,#courseMainBox')||document.body;
    return [body,...$$('*',body)].find(e=>visible(e)&&e.clientHeight>80&&e.scrollHeight>e.clientHeight+8&&/auto|scroll/.test(getComputedStyle(e).overflowY))||document.scrollingElement;
  }
  async function readTick(){
    const now=Date.now();
    if(S.reading){const t=GM_getValue(TICKET,null);if(t?.id!==S.reading.id||t.state!=='active'){pause('阅读已暂停');return;}GM_setValue(TICKET,{...t,lastSeen:now});}
    if(!$('#ztMainBoxFocus')&&readerLinks().length){
      const seen=new Set(GM_getValue(`cirno.read.${new URL(readerLinks()[0].href).searchParams.get('courseId')}`,[]));
      const first=readerLinks().find(a=>!seen.has(new URL(a.href).searchParams.get('knowledgeId')));
      if(first){location.assign(first.href);return;}
      finishReading();return;
    }
    const signature=readIdentity();
    if(signature!==S.readerSignature){S.readerSignature=signature;S.readerSince=now;S.readerBottom=0;S.readerPending=null;S.readerLast=now;progress();}
    if(S.readerPending){if(now-S.readerPending>25000)fault('阅读翻页未响应');return;}
    const u=new URL(location.href),book=u.searchParams.get('courseId'),chapter=u.searchParams.get('knowledgeId');
    const next=readerNext();
    if(book&&chapter&&GM_getValue(`cirno.read.${book}`,[]).includes(chapter)){
      if(next){S.readerPending=now;next.click();status('跳过已阅读页');}else finishReading();return;
    }
    const scroller=readerScroller();
    if(!scroller)return;
    const height=scroller===document.scrollingElement?innerHeight:scroller.clientHeight;
    const seconds=Math.min(2,Math.max(.1,(now-(S.readerLast||now-1500))/1000));S.readerLast=now;
    const step=Math.max(1,Math.min(1200,Math.max(10,Number(cfg.readSpeed)||80))*seconds);
    if(scroller.scrollTop+height<scroller.scrollHeight-8){
      if(S.readerTop!==scroller.scrollTop){S.readerTop=scroller.scrollTop;progress();}
      if(scroller===document.scrollingElement)window.scrollBy({top:step,behavior:'smooth'});else scroller.scrollBy({top:step,behavior:'smooth'});
      status(`缓慢阅读 · ${cfg.readSpeed} 像素/秒`);return;
    }
    if(!S.readerBottom){S.readerBottom=now;return;}
    if(now-S.readerSince<cfg.readSeconds*1000||now-S.readerBottom<1500){status('已到页尾');return;}
    if(book&&chapter){const k=`cirno.read.${book}`,seen=new Set(GM_getValue(k,[]));seen.add(chapter);GM_setValue(k,[...seen]);}
    if(next){S.readerPending=now;next.click();status('阅读下一页');return;}
    const more=$('#loadbutton');if(visible(more)){
      const before=more.getAttribute('onclick');more.click();S.readerSince=now;S.readerBottom=0;
      await sleep(1500);if(more.isConnected&&more.getAttribute('onclick')===before){fault('阅读内容未加载');}return;
    }
    if($('#ztMainBoxFocus')||$('#courseMainBox'))finishReading();else fault('未识别阅读正文');
  }
  function finishReading(){
    const t=GM_getValue(TICKET,null);if(S.reading&&t?.id===S.reading.id)GM_setValue(TICKET,{...t,state:'done'});
    sessionStorage.removeItem('cirno.readSession');pause('阅读完成');
  }
  function waitContent(message){if(/视频/.test($('[id^="dct"].active')?.title||'')){videoWatchdog(null,message);return;}if(Date.now()-S.changed>45000)recoverPage(message+'超时');else status(message);}
  async function tick(){
    if(S.busy||!S.started)return;
    if(S.waitReader){await waitReader();return;}
    if(!ownsLease()){pause('运行已转交其他页面');return;}
    renewLease();
    S.busy=true;
    try{
      if(readerPage){await readTick();return;}
      const key=pageKey();
      if(key!==S.key){S.key=key;S.changed=Date.now();S.epoch++;S.pending=null;S.submit=null;S.videoWatch=null;S.lastVideoProgress=0;S.failed.clear();S.quiz.clear();}
      if(S.pending){if(Date.now()-S.pending.at>25000)recoverPage('页面未跳转，请检查前置条件');return;}
      if(Date.now()-S.changed<4500){status('加载中');return;}
      if(prioritizeVideo())return;
      if(!$('#iframe')&&$('#mainid')&&Date.now()-S.changed>=10000){advance();return;}
      const card=cardDoc();
      if(!card?.body||card.readyState==='loading'){waitContent('等待内容加载');return;}
      if(handleSubmission())return;
      const ctx=currentEpoch(),docs=documents(card),wrappers=$$('.ans-attach-ct',card);
      if(cfg.fullAuto)wrappers.sort((a,b)=>Number(!/\/video\//.test($('iframe',a)?.getAttribute('src')||''))-Number(!/\/video\//.test($('iframe',b)?.getAttribute('src')||'')));
      for(const d of docs){const q=popup(d);if(q){await solvePopup(q,ctx);return;}}
      const activeTitle=$('[id^="dct"].active')?.title||'';
      if(/问卷|调查/.test(activeTitle+text($('#mainid>h1,#mainid>h2')))){advance();return;}
      for(const wrapper of wrappers){
        const f=$('iframe',wrapper),src=f?.getAttribute('src')||'';
        const marker=$('.ans-job-icon',wrapper),done=taskDone(marker)||wrapper.classList.contains('ans-job-finished');
        if(/\/read\//.test(src)){
          if(cfg.reading){await openReader(f.contentDocument);return;}continue;
        }
        if(done)continue;
        if(/\/video\//.test(src)){
          if(!cfg.video)continue;
          const v=documents(f.contentDocument).flatMap(d=>$$('video',d))[0];
          if(v)await playVideo(v);else videoWatchdog(null,'等待视频加载');return;
        }
        if(/\/work\//.test(src)){
          if(!cfg.homework&&!S.single)continue;
          const d=documents(f.contentDocument).find(d=>questionRoots(d).length||submitButton(d));
          if(d)await doHomework(d,ctx);else waitContent('等待习题加载');return;
        }
        if(marker&&!done){fault('遇到尚未适配的任务类型');return;}
      }
      const videos=docs.flatMap(d=>$$('video',d));
      if(videos.length&&!wrappers.length&&cfg.video){const v=videos.find(v=>!v.ended);if(v){await playVideo(v);return;}}
      const work=!wrappers.some(w=>/\/work\//.test($('iframe',w)?.getAttribute('src')||''))&&docs.find(d=>questionRoots(d).length);
      if(work){await doHomework(work,ctx);return;}
      const unloaded=$$('iframe',card).filter(visible).some(f=>{try{return !f.contentDocument?.body||f.contentDocument.readyState==='loading';}catch{return true;}});
      if(unloaded){waitContent('等待嵌入内容');return;}
      if(!wrappers.length&&$$('iframe',card).some(f=>/\/modules\/(video|work|read)\//.test(f.getAttribute('src')||''))){waitContent('等待任务控件');return;}
      if(!wrappers.length&&/视频/.test(activeTitle)&&Date.now()-S.changed<20000){status('检查视频页面');return;}
      if(Date.now()-S.changed>=( $('#pageDiv',card)?7000:12000))advance();else status('检查无视频内容');
    }catch(e){status(e.message||'页面处理失败');}
    finally{S.busy=false;}
  }

  const BANK='baka.answerBank.v1';
  cfg={collectAnswers:false,useAnswerBank:false,...cfg};
  const bankText=v=>String(v??'').normalize('NFKC').replace(/\s+/g,' ').trim();
  const bankTitle=v=>bankText(v).replace(/^\d+\s*[.、．]?\s*(?=[【\[])/,'').replace(/^[【\[][^】\]]*(?:选|判断|填空|简答)[^】\]]*[】\]]\s*/,'');
  function bankQuestion(q){return {title:bankTitle(q.title),type:q.type,judge:!!q.judge,visual:!!q.visual,course:String(courseId()||''),questionId:String(q.id||''),options:q.options.map(o=>({label:o.label,value:String(o.value||o.label),text:bankText(text($('a',o.el))||o.text.replace(new RegExp('^'+o.label+'[.、．]?\\s*'),''))}))};}
  function bankKey(e){return JSON.stringify([e.type,e.judge,e.visual?e.course:'',e.visual?e.questionId:'',e.title,e.options.map(o=>o.text).sort()]);}
  function bankAnswerKey(e){return JSON.stringify([e.answer.choices.map(l=>e.options.find(o=>o.label===l)?.text).sort(),e.answer.blanks,e.answer.answer]);}
  function bankEntries(){return GM_getValue(BANK,[]);}
  function bankParseQuestion(root){
    const q=parseQuestion(root);
    if(q.judge&&!q.options.length){q.type='single';q.options=[{label:'A',value:'true',text:'对',el:null},{label:'B',value:'false',text:'错',el:null}];}
    return q;
  }
  function cleanBankEntry(e,imported=false){
    const str=(v,max=16000)=>{if(typeof v!=='string'||v.length>max)throw Error('题库字段格式不正确');return v;};
    if(!e||!['single','multi','blanks','text'].includes(e.type)||typeof e.judge!=='boolean'||typeof e.visual!=='boolean'||!Array.isArray(e.options)||e.options.length>26||!e.answer)throw Error('题库题型或选项格式不正确');
    const result={title:str(e.title),type:e.type,judge:e.judge,visual:e.visual,course:str(e.course,200),questionId:str(e.questionId,200),options:e.options.map(o=>({label:str(o.label,1),value:str(o.value,200),text:str(o.text)}))};
    if(!result.title||result.options.some(o=>! /^[A-Z]$/.test(o.label)||!o.text)||new Set(result.options.map(o=>o.label)).size!==result.options.length)throw Error('题库题干或选项缺失');
    const a=e.answer;if(!Array.isArray(a.choices)||!Array.isArray(a.blanks)||a.choices.length>26||a.blanks.length>100)throw Error('题库答案格式不正确');
    result.answer={choices:a.choices.map(x=>str(x,1)).sort(),blanks:a.blanks.map(x=>str(x)),answer:str(a.answer)};
    if(result.options.length){if(!a.choices.length||new Set(a.choices).size!==a.choices.length||(e.type==='single'&&a.choices.length!==1)||a.choices.some(l=>!result.options.some(o=>o.label===l)))throw Error('题库答案与选项不匹配');result.answer.blanks=[];result.answer.answer='';}
    else if(e.type==='blanks'){if(!a.blanks.length||a.blanks.some(v=>!v.trim()))throw Error('填空答案缺失');result.answer.choices=[];result.answer.answer='';}
    else if(e.type==='text'){if(!a.answer.trim())throw Error('文字答案缺失');result.answer.choices=[];result.answer.blanks=[];}
    else throw Error('选择题选项缺失');
    result.source=imported?'imported':e.source==='imported'?'imported':'platform';
    result.key=bankKey(result);result.id=JSON.stringify([result.key,bankAnswerKey(result)]);return result;
  }
  function mergeBank(records,imported=false){
    const clean=records.map(e=>cleanBankEntry(e,imported)),all=bankEntries(),map=new Map(all.map(e=>[e.id,e]));let added=0;
    for(const e of clean){if(!map.has(e.id)){map.set(e.id,e);added++;}else if(!imported&&e.source==='platform')map.set(e.id,e);}
    GM_setValue(BANK,[...map.values()]);ui.updateBank?.();return added;
  }
  function explicitCorrect(q){
    const candidates=$$('div,p,span,li,dd',q.root).filter(visible).map(e=>text(e)).filter(s=>/^(?:正确答案|参考答案)\s*[:：]/.test(s)).sort((a,b)=>a.length-b.length);
    for(const box of $$('.newAnswerBx .myAnswerBx',q.root).filter(visible)){
      const marks=$$('.CorrectOrNot [class*="marking_"]',box).filter(visible);
      if(marks.length===1&&marks[0].classList.contains('marking_dui')){
        const own=$('.myAnswer .answerCon',box);if(visible(own)&&text(own))candidates.push('正确答案：'+text(own));
      }
    }
    for(const s of candidates){
      const raw=s.replace(/^(?:正确答案|参考答案)\s*[:：]\s*/,'').split(/(?:我的答案|学生答案|您的答案|答案解析|解析|得分)\s*[:：]/)[0].trim();if(!raw)continue;
      const a={choices:[],blanks:[],answer:''};
      if(q.options.length){
        if(q.judge&&/^(正确|错误|对|错|true|false|√|×|✓|✗)$/i.test(raw)){a.answer=raw;try{validateAnswer(q,a);}catch{continue;}}
        else if(/^[A-Z](?:\s*[,，、;；.．]?\s*[A-Z])*[.。]?$/.test(raw))a.choices=[...new Set(raw.match(/[A-Z]/g))];
        else continue;
        try{validateAnswer(q,a);}catch{continue;}
      }else if(q.type==='blanks'){a.blanks=raw.split(/[;；\n]+/).map(bankText).filter(Boolean);}
      else if(q.type==='text')a.answer=raw;else continue;
      return a;
    }return null;
  }
  function collectBank(manual=false){
    if(!manual&&!cfg.collectAnswers)return 0;
    const entries=[];
    for(const d of documents(cardDoc()||document)){
      if(/\/exam\//i.test(d.location.pathname))continue;
      for(const root of questionRoots(d)){
        const q=bankParseQuestion(root),a=explicitCorrect(q);if(!a)continue;
        try{entries.push(cleanBankEntry({...bankQuestion(q),answer:a,source:'platform'}));}catch{}
      }
    }
    if(!entries.length)return 0;
    // Repeated result polling must not rewrite storage or reset the selection list.
    const existing=new Map(bankEntries().map(e=>[e.id,e]));const fresh=entries.filter(e=>!existing.has(e.id)||existing.get(e.id).source!=='platform');
    return fresh.length?mergeBank(fresh):0;
  }
  function bankBeforeAdvance(){
    if(!cfg.collectAnswers)return false;
    collectBank();const key=pageKey();
    const results=documents(cardDoc()||document).some(d=>$('.newAnswerBx',d)||questionRoots(d).some(r=>!!explicitCorrect(parseQuestion(r))));
    if(!S.submit&&!results&&S.bankWait?.key!==key)return false;
    if(S.bankWait?.key!==key)S.bankWait={key,at:Date.now()};
    if(Date.now()-S.bankWait.at<3000){status('正在收集平台公布的正确答案');return true;}return false;
  }
  function bankLookup(q){
    if(!cfg.useAnswerBank)return null;
    if($('img,svg,canvas',q.root))return null;
    const probe=bankQuestion(q),key=bankKey(probe),matches=bankEntries().filter(e=>e.key===key);
    if(!matches.length)return null;
    if(new Set(matches.map(bankAnswerKey)).size!==1){log('题库存在冲突答案，交由 AI 重新判断');return null;}
    const e=matches[0],a={choices:[],blanks:[...e.answer.blanks],answer:e.answer.answer,uncertain:false,explanation:e.source==='imported'?'来自导入题库':'来自平台正确答案题库'};
    if(new Set(probe.options.map(o=>o.text)).size!==probe.options.length)return null;
    for(const l of e.answer.choices){const content=e.options.find(o=>o.label===l)?.text,option=probe.options.find(o=>o.text===content);if(!option)return null;a.choices.push(option.label);}
    try{validateAnswer(q,a);}catch{return null;}return a;
  }
  function bankExport(ids=null){
    const entries=bankEntries().filter(e=>!ids||ids.has(e.id)).map(e=>{const c=cleanBankEntry(e);const {title,type,judge,visual,course,questionId,options,answer}=c;return {title,type,judge,visual,course,questionId,options,answer};});
    return JSON.stringify({format:'baka-answer-bank',version:1,entries},null,2);
  }
  function bankImport(value){
    if(typeof value!=='string'||new Blob([value]).size>10*1024*1024)throw Error('题库文件不能超过 10 MB');
    let data;try{data=JSON.parse(value);}catch{throw Error('文件不是有效 JSON 题库');}
    if(data?.format!=='baka-answer-bank'||data.version!==1||!Array.isArray(data.entries)||data.entries.length>10000)throw Error('请选择 Baka 题库文件（最多 10000 条）');
    return {added:mergeBank(data.entries,true),read:data.entries.length};
  }
  function bankDownload(value){
    const blob=new Blob([value],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Baka题库-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);
  }
  function mountBank(root){
    const nav=$('.tabs',root),tab=document.createElement('button');tab.dataset.tab='bank';tab.textContent='题库';nav.append(tab);
    const pane=document.createElement('div');pane.dataset.pane='bank';pane.hidden=true;
    pane.innerHTML='<label class="switch">自动收集正确答案<input type="checkbox" data-setting="collectAnswers"></label><label class="switch">优先使用题库答案<input type="checkbox" data-setting="useAnswerBank"></label><div class="sub bankStats"></div><div class="row"><button class="btn bankCollect">收集当前页</button><button class="btn bankImport">导入题库</button></div><div class="row"><button class="btn bankExport">导出全部</button><button class="btn bankSelected">导出所选</button></div><button class="btn bankShare">分享题库文件</button><input class="bankFile" type="file" accept=".json,application/json" hidden><label class="field"><span>搜索题目</span><input class="bankSearch" type="search"></label><label class="switch">选择本页<input class="bankAll" type="checkbox"></label><div class="bankList"></div><div class="row"><button class="btn bankPrev">上一页</button><span class="bankPage"></span><button class="btn bankNext">下一页</button></div><div class="sub">收集公布答案或逐题判对的答案。导入文件需确认来源；冲突答案不自动使用。</div>';
    $('.foot',root).before(pane);mountBankScan(pane);let page=0;const selected=new Set();
    const search=$('.bankSearch',pane),list=$('.bankList',pane),all=$('.bankAll',pane);
    ui.updateBank=()=>{
      const entries=bankEntries(),groups=new Map();for(const e of entries){if(!groups.has(e.key))groups.set(e.key,new Set());groups.get(e.key).add(bankAnswerKey(e));}
      const conflicts=[...groups.values()].filter(s=>s.size>1).length;
      $('.bankStats',pane).textContent=`${groups.size} 道题 · ${entries.length} 条答案 · ${entries.filter(e=>e.source==='imported').length} 条导入 · ${conflicts} 题冲突 · 已选 ${selected.size}`;
      const filtered=entries.filter(e=>(e.title+' '+e.questionId+' '+e.course).toLowerCase().includes(search.value.trim().toLowerCase()));
      const pages=Math.max(1,Math.ceil(filtered.length/30));page=Math.min(page,pages-1);const slice=filtered.slice(page*30,page*30+30);list.replaceChildren();
      for(const e of slice){const label=document.createElement('label');label.style.cssText='display:flex;gap:8px;padding:9px 0;border-bottom:1px solid #cde0ec;overflow-wrap:anywhere';const box=document.createElement('input');box.type='checkbox';box.checked=selected.has(e.id);box.onchange=()=>{box.checked?selected.add(e.id):selected.delete(e.id);ui.updateBank();};const span=document.createElement('span');span.textContent=e.title+'\n答案：'+(e.answer.choices.join('、')||e.answer.blanks.join('；')||e.answer.answer)+(e.visual?' · 字体/图片题':'')+(groups.get(e.key).size>1?' · 冲突':'');span.style.whiteSpace='pre-wrap';label.append(box,span);list.append(label);}
      all.checked=slice.length>0&&slice.every(e=>selected.has(e.id));all.indeterminate=slice.some(e=>selected.has(e.id))&&!all.checked;all.onchange=()=>{for(const e of slice)all.checked?selected.add(e.id):selected.delete(e.id);ui.updateBank();};
      $('.bankPage',pane).textContent=`${page+1} / ${pages}`;$('.bankPrev',pane).disabled=page===0;$('.bankNext',pane).disabled=page===pages-1;$('.bankSelected',pane).disabled=!selected.size;
    };
    search.oninput=()=>{page=0;ui.updateBank();};$('.bankPrev',pane).onclick=()=>{page--;ui.updateBank();};$('.bankNext',pane).onclick=()=>{page++;ui.updateBank();};
    $('.bankCollect',pane).onclick=()=>{try{const count=collectBank(true);ui.updateBank();status(`新增 ${count} 条正确答案；支持公布答案和逐题判对结果`);}catch(e){status(e.message);}};
    $('.bankExport',pane).onclick=()=>bankDownload(bankExport());$('.bankSelected',pane).onclick=()=>bankDownload(bankExport(selected));
    const input=$('.bankFile',pane);$('.bankImport',pane).onclick=()=>input.click();input.onchange=async()=>{try{const f=input.files?.[0];if(!f)return;if(f.size>10*1024*1024)throw Error('题库文件不能超过 10 MB');const r=bankImport(await f.text());status(`已导入 ${r.added} 条新答案，${r.read-r.added} 条重复`);}catch(e){status(e.message);}finally{input.value='';}};
    $('.bankShare',pane).onclick=async()=>{const data=bankExport(selected.size?selected:null);try{const file=new File([data],'Baka题库.json',{type:'application/json'});if(navigator.canShare?.({files:[file]})&&navigator.share){await navigator.share({files:[file],title:'Baka题库'});}else{bankDownload(data);status('已导出题库文件，可发送到其他电脑后导入');}}catch(e){if(e.name!=='AbortError'){bankDownload(data);status('系统分享不可用，已改为下载题库文件');}}};
    ui.updateBank();
  }

  const SCAN=`baka.bankScan.v1.${owner}`;
  let scanEpoch=0;
  function saveBankScan(){const s=S.bankScan;if(!s)return;const {course,ids,index,doneCards,pages,added,skipped,active}=s;GM_setValue(SCAN,{course,ids,index,doneCards,pages,added,skipped,active,at:Date.now()});ui.updateScan?.();}
  function stopBankScan(message='顺序收集已停止'){
    scanEpoch++;if(!S.bankScan?.active)return;S.bankScan.active=false;saveBankScan();release();status(message);
  }
  function restoreBankScan(){
    const saved=GM_getValue(SCAN,null);if(saved&&saved.course===courseId()&&Array.isArray(saved.ids)&&saved.index<saved.ids.length){S.bankScan={...saved,active:false,phase:'chapter',at:Date.now()};saveBankScan();}
  }
  async function startBankScan(resume=false){
    if(readerPage||overviewPage||!catalogue().length){status('请在课程章节页启动顺序收集');return;}
    pause('准备顺序收集');const token=++scanEpoch;
    if(!await acquire())return;if(token!==scanEpoch){release();return;}
    const saved=resume?GM_getValue(SCAN,null):null;
    const reuse=saved&&saved.course===courseId()&&Array.isArray(saved.ids)&&saved.index<saved.ids.length;
    S.bankScan=reuse?{...saved}:{course:courseId(),ids:[...new Set(catalogue().map(x=>x.id))],index:0,doneCards:[],pages:0,added:0,skipped:0};
    Object.assign(S.bankScan,{active:true,phase:'chapter',at:Date.now(),waitDoc:null,signature:null});
    saveBankScan();status('顺序收集已开始');await bankScanTick();
  }
  function scanMove(el,phase){const s=S.bankScan;s.waitDoc=cardDoc();s.phase=phase;s.at=Date.now();s.signature=null;saveBankScan();el.click();}
  function scanNextChapter(skipped=false){const s=S.bankScan;if(skipped)s.skipped++;s.index++;s.doneCards=[];s.target=null;s.waitDoc=null;s.phase='chapter';s.at=Date.now();saveBankScan();}
  function scanDoneCard(skipped=false){const s=S.bankScan;if(skipped)s.skipped++;s.pages++;s.doneCards.push(s.target);s.target=null;s.waitDoc=null;s.phase='cards';s.at=Date.now();saveBankScan();}
  async function bankScanTick(){
    const s=S.bankScan;if(!s?.active)return false;
    if(courseId()!==s.course){stopBankScan('课程已切换，顺序收集已停止');return true;}
    if(!ownsLease()){stopBankScan('其他页面取得运行权，顺序收集已停止');return true;}
    renewLease();
    if(verificationPresent()||pageError()){stopBankScan('遇到登录、验证或页面异常；处理后可继续收集');return true;}
    if(s.index>=s.ids.length){stopBankScan(`顺序收集完成 · 检查 ${s.pages} 页 · 新增 ${s.added} 条 · 跳过 ${s.skipped} 项`);return true;}
    status(`顺序收集 ${s.index+1}/${s.ids.length} 节 · 新增 ${s.added} 条`);
    const target=s.ids[s.index],age=Date.now()-s.at;
    if(s.phase==='chapter'){
      if(chapterId()!==target){const item=catalogue().find(x=>x.id===target);if(!item){scanNextChapter(true);return true;}scanMove(item.el,'chapterWait');return true;}
      s.phase='cards';s.at=Date.now();return true;
    }
    if(s.phase==='chapterWait'){
      if(chapterId()===target&&cardDoc()&&cardDoc()!==s.waitDoc&&cardDoc().readyState==='complete'&&age>=1500){s.phase='cards';s.at=Date.now();s.waitDoc=null;}
      else if(age>30000)scanNextChapter(true);return true;
    }
    if(chapterId()!==target){stopBankScan('章节被手动切换；可点击继续收集');return true;}
    if(s.phase==='cards'){
      if(age<2000)return true;
      const cards=$$('[id^="dct"][cardid]').filter(el=>cardRank(el)===1),next=cards.find(el=>!s.doneCards.includes(el.id));
      if(!next){scanNextChapter();return true;}
      s.target=next.id;
      if(!next.classList.contains('active'))scanMove(next,'cardWait');else{s.phase='result';s.at=Date.now();s.signature=null;}
      return true;
    }
    if(s.phase==='cardWait'){
      if($('#'+s.target)?.classList.contains('active')&&cardDoc()&&cardDoc()!==s.waitDoc&&cardDoc().readyState==='complete'&&age>=1500){s.phase='result';s.at=Date.now();s.waitDoc=null;}
      else if(age>30000)scanDoneCard(true);return true;
    }
    if(s.phase==='result'){
      if(!$('#'+s.target)?.classList.contains('active')){stopBankScan('学习内容被切换；可点击继续收集');return true;}
      const docs=documents(cardDoc()),roots=docs.flatMap(d=>questionRoots(d));
      const signature=roots.map(r=>r.id+' '+text(r)).join('|');
      if(signature!==s.signature){s.signature=signature;s.stableAt=Date.now();}
      if(roots.length&&age>=3000&&Date.now()-s.stableAt>=1500){
        const added=collectBank(true);s.added+=added;
        const available=roots.some(r=>explicitCorrect(bankParseQuestion(r)));
        scanDoneCard(!available);return true;
      }
      if(age>20000)scanDoneCard(true);return true;
    }
    return true;
  }
  function mountBankScan(pane){
    const box=document.createElement('div');box.innerHTML='<hr class="divider"><div class="sub">独立收集：按目录顺序浏览章节测验，不做题、不提交</div><div class="row"><button class="btn scanStart">从第一节收集</button><button class="btn scanResume">继续收集</button></div><button class="btn scanStop">停止收集</button><div class="sub scanProgress"></div>';
    pane.prepend(box);
    $('.scanStart',box).onclick=()=>void startBankScan(false);$('.scanResume',box).onclick=()=>void startBankScan(true);$('.scanStop',box).onclick=()=>stopBankScan();
    ui.updateScan=()=>{const s=S.bankScan;$('.scanStart',box).disabled=!!s?.active;$('.scanResume',box).disabled=!!s?.active||!s||s.index>=s.ids.length;$('.scanStop',box).disabled=!s?.active;$('.scanProgress',box).textContent=s?`${s.active?'收集中':'已停止'} · ${Math.min(s.index+1,s.ids.length)}/${s.ids.length} 节 · ${s.pages} 页 · 新增 ${s.added} 条 · 跳过 ${s.skipped} 项`:'';};restoreBankScan();ui.updateScan();
  }

